$$\begin{array}{l}
  {{\int{x^{2}\ln xdx}} = {\int{udv = uv - {\int{vdu}}}}} \\
  {\phantom{\int{x^{2}\ln xdx}} = {\frac{1}{3}x^{3}\ln x - {\int{\frac{1}{3}x^{2}dx}}}} \\
  {\phantom{\int{x^{2}\ln xdx}} = {\frac{1}{3}x^{3}\ln x - \frac{1}{9}x^{3} + C}} \\
  {\phantom{\int{x^{2}\ln xdx}} = {\frac{1}{9}x^{3}\left( {3\ln x - 1} \right) + C}}
  \end{array}$$

$$\begin{array}{l}
  {{2{\int{\frac{x}{\sqrt{3 + x}}dx}}}{= 2\left\lbrack {\frac{2}{3(1)}\left( {x - 6} \right)\sqrt{3 + x}} \right\rbrack + C}} \\
  {\phantom{2{\int{\frac{x}{\sqrt{3 + x}}dx}}}{= \frac{4}{3}\left( {x - 6} \right)\sqrt{3 + x} + C}}
  \end{array}$$

$$\begin{array}{l}
  {\left\lbrack \frac{f{(x_{0})} + f{(x_{1})}}{2} \right\rbrack ‍\Delta x + \left\lbrack \frac{f{(x_{1})} + f{(x_{2})}}{2} \right\rbrack ‍\Delta x + \ldots + \left\lbrack \frac{f{(x_{n - 1})} + f{(x_{n})}}{2} \right\rbrack ‍\Delta x} \\
  {\mspace{20mu} = \frac{\Delta x}{2}\left\lbrack {f{(x_{0})} + f{(x_{1})} + f{(x_{1})} + f{(x_{2})} + \ldots + f{(x_{n - 1})} + f{(x_{n})}} \right\rbrack} \\
  {\mspace{20mu} = \frac{\Delta x}{2}\left\lbrack {f{(x_{0})} + 2f{(x_{1})} + 2f{(x_{2})} + \ldots + 2f{(x_{n - 1})} + f{(x_{n})}} \right\rbrack}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + f\left( x_{2} \right)} \right\rbrack + \frac{\Delta x}{3}\left\lbrack {f\left( x_{2} \right) + 4f\left( x_{3} \right) + f\left( x_{4} \right)} \right\rbrack + \cdots + \frac{\Delta x}{3}\left\lbrack {f\left( x_{n - 2} \right) + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack} \\
  {\quad = \frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + f\left( x_{2} \right) + f\left( x_{2} \right) + 4f\left( x_{3} \right) + f\left( x_{4} \right) + \cdots + f\left( x_{n - 2} \right) + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack} \\
  {\quad = \frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + 2f\left( x_{2} \right) + 4f\left( x_{3} \right) + 2f\left( x_{4} \right) + \cdots + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{- \infty}^{0}{xe^{- x^{2}}dx}} = \lim\limits_{a\rightarrow - \infty}{\int_{a}^{0}{xe^{- x^{2}}dx}}} \\
  {\phantom{\int_{- \infty}^{\infty}{xe^{- x^{2}}dx}} = \left. \lim\limits_{a\rightarrow - \infty} - \frac{1}{2}e^{- x^{2}} \right|_{a}^{0}} \\
  {\phantom{\int_{- \infty}^{\infty}{xe^{- x^{2}}dx}} = {\lim\limits_{a\rightarrow - \infty}\left\lbrack {- \frac{1}{2} + \frac{1}{2}e^{- a^{2}}} \right\rbrack = - ‍\frac{1}{2}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{0}^{\infty}{xe^{- x^{2}}dx}} = \lim\limits_{b\rightarrow\infty}\int_{0}^{b}{xe^{- x^{2}}dx}} \\
  {\phantom{\int_{0}^{\infty}{xe^{- x^{2}}dx}} = \left. \lim\limits_{b\rightarrow\infty} - \frac{1}{2}e^{- x^{2}} \right|_{0}^{b}} \\
  {\phantom{\int_{0}^{\infty}{xe^{- x^{2}}dx}} = {\lim\limits_{b\rightarrow\infty}\left( {- \frac{1}{2}e^{- b^{2}} + \frac{1}{2}} \right) = ‍\frac{1}{2}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{- \infty}^{\infty}{xe^{- x^{2}}dx}} = {\int_{- \infty}^{0}{xe^{- x^{2}}dx + {\int_{0}^{\infty}{xe^{- x^{2}}dx}}}}} \\
  {\phantom{\int_{- \infty}^{\infty}{xe^{- x^{2}}dx}}{= - {\int_{0}^{\infty}{xe^{- x^{2}}dx + {\int_{0}^{\infty}{xe^{- x^{2}}dx}}}}}} \\
  {\phantom{\int_{- \infty}^{\infty}{xe^{- x^{2}}dx}}{= 0}}
  \end{array}$$

$$\begin{array}{l}
  {{mP{\int_{0}^{\infty}{e^{- rt}dt}}}{= \lim\limits_{b\rightarrow\infty}mP{\int_{0}^{b}{e^{- rt}dt}}}} \\
  {\phantom{mP{\int_{0}^{\infty}{e^{- rt}dt}}}{= mP\lim\limits_{b\rightarrow\infty}{\int_{0}^{b}{e^{- rt}dt}}}} \\
  {\phantom{mP{\int_{0}^{\infty}{e^{- rt}dt}}}{= mP\lim\limits_{b\rightarrow\infty}\left( \left. - ‍\frac{1}{r}e^{- rt} \right|_{0}^{b} \right)}} \\
  {\phantom{mP{\int_{0}^{\infty}{e^{- rt}dt}}}{= mP\lim\limits_{b\rightarrow\infty}\left( {- ‍\frac{1}{r}e^{- rb} + \frac{1}{r}} \right) = \frac{mP}{r}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{- \infty}^{0}\frac{x^{3}}{\left( {1 + x^{4}} \right)^{3 \slash 2}}dx}{= \lim\limits_{a\rightarrow - \infty}{\int_{a}^{0}{x^{3}‍{({1 + x^{4}})}^{- 3 \slash 2}dx}}}} \\
  {\phantom{\int_{- \infty}^{0}\frac{x^{3}}{{({1 + x^{4}})}^{3 \slash 2}}dx}{= \left. \lim\limits_{a\rightarrow - \infty}\frac{1}{4}\left( {- 2} \right){({1 + x^{4}})}^{- 1 \slash 2} \right|_{a}^{0}}\qquad\begin{array}{l}
  {Integrate\ by} \\
  {substitution.}
  \end{array}} \\
  {\phantom{\int_{- \infty}^{0}\frac{x^{3}}{\left( {1 + x^{4}} \right)^{3 \slash 2}}dx}{= - ‍\frac{1}{2}\lim\limits_{a\rightarrow - \infty}\left\lbrack {1 - \frac{1}{\left( {1 + a^{4}} \right)^{1 \slash 2}}} \right\rbrack}} \\
  {\phantom{\int_{- \infty}^{0}\frac{x^{3}}{\left( {1 + x^{4}} \right)^{3 \slash 2}}dx}{= - ‍\frac{1}{2}}}
  \end{array}$$
